import React, {useRef, useState, useEffect, forwardRef, useContext} from "react";
import {Table} from "@douyinfe/semi-ui";
import {
  getSize,
  getDatas,
  commonInfo,
} from "./const";
import ConfigContext from "./ConfigContext";
import Cell from "./Cell";
import {cloneDeep} from "@douyinfe/semi-ui/lib/es/_utils";
import {line_computed, my_plat, show_columns} from "../utils/computed";
import { notEqualsFilter } from '../utils/filter'



let scrollTimer = null

const VirtualizedFixedDemo = forwardRef((props, ref) => {
  const {deepConfig, setDeepConfig, appHeight, mainTheme, currentTheme} = useContext(ConfigContext)
  const {
    bitableContext,
    renderLoading,
  } = props;

  let virtualizedListRef = useRef();
  const scrollPanel = useRef()
  const [scroll, setScroll] = useState({});
  const [virtualized, setVirtualized] = useState({});
  const [tableDatas, setTableDatas] = useState([]);
  const [tableComponent, setTableComponent] = useState()
  const {
    bitable,
    loading
  } = bitableContext ?? {};

  // commonInfo.virtualizedListRef = virtualizedListRef;
  commonInfo.deepConfig = deepConfig;

  useEffect(() => {
    if (deepConfig.data_sorce && !loading) {
      getTableDataById(deepConfig.data_sorce)
    }

    document.getElementById('scroll-table-container').addEventListener('wheel', function(event) {
      event.preventDefault();
    }, { passive: false });
  }, [loading]);

  useEffect(() => {
    if (deepConfig.data_sorce && !loading) {
      getTableDataById(deepConfig.data_sorce)
    }
  }, [deepConfig, deepConfig.data_sorce, loading])

  useEffect(() => {
    resizeByHeight()
  }, [appHeight]);

  const resizeByHeight = () => {
    if (appHeight) {
      getSize(appHeight, tableDatas.length).then((res) => {
        setScroll({ y: res.y, x: res.x });
        setVirtualized({
          itemSize: res.itemSize,
        });
        const tbody = document.querySelectorAll('.semi-table-tbody')
        if (tbody && tbody.length) {
          tbody.forEach((d, i) => {
            d.querySelectorAll('.semi-table-row').forEach((ele, i) => {
              ele.style.setProperty('height', `${res.itemSize}px`)
              ele.style.setProperty('top', `${i * res.itemSize }px`)
            })
          })
        }
        initScroll(res.itemSize)
      });
    }
  }

  const resizeByRow = (tableLength, hasDivider = false) => {
    if (appHeight) {
      getSize(appHeight, tableLength).then((res) => {
        setScroll({ y: res.y, x: res.x });
        setVirtualized({
          itemSize: res.itemSize,
        });
        const tbody = document.querySelectorAll('.semi-table-tbody')
        if (tbody && tbody.length) {
          tbody.forEach((d, i) => {
            d.querySelectorAll('.semi-table-row').forEach((ele, i) => {
              ele.style.setProperty('height', `${res.itemSize}px`)
              ele.style.setProperty('top', `${i * res.itemSize }px`)
            })
          })
        }
        initScroll(res.itemSize, tableLength, hasDivider)
      });
    }
  }

  const getLineComputed = () => { // 根据设备获取行数
    return my_plat(deepConfig) === 'pc'
      ? deepConfig.pc_line
      : deepConfig.phone_line
  }

  const getColumns = () => { // 获取列数据
    return show_columns(deepConfig).map((d, index) => {
      return {
        title: d?.name,
        dataIndex: d?.id,
        type: d?.type,
        width: '30%',
        render: (text, row, index) => {
          return (
            <ConfigContext.Provider value={{tableComponent, setTableComponent, appHeight, deepConfig}}>
              <Cell
                col={d}
                row={row}
                index={index}
                text={text}
                table={tableComponent}
              />
            </ConfigContext.Provider>
          )
        }
      }
    })
  }

  const getTableDataById = async id => { // 根据id获取列表数据
    if (!bitable) {
      return setTableDatas([])
    }
    const table = await bitable.base.getTable(id)
    setTableComponent(table)
    getDatas(table).then(res => {
      const length = getLineComputed()
      
      const orderStatusField = deepConfig.all_fields?.find(f => f.name === '订单状态')
      
      let result = res

      if (orderStatusField) {
        result = res.filter(d => {
          const cellValue = d[orderStatusField.id]
          return notEqualsFilter(cellValue, '已完成')
        })
      }
      
      let hasDivider = false
      if (result.length && result.length > length) {
        hasDivider = true
        result = result.map(d => Object.assign(cloneDeep(d), { key: d.recordId || Math.random() }))
        result.push({ isDividerRow: true, key: 'divider-row' })
      } else {
        result = result.map((d, i) => {
          return Object.assign(cloneDeep(d), {
            key: d.recordId || Math.random()
          })
        })
      }
      
      setTableDatas(result)
      resizeByRow(result.length, hasDivider)
    })
  }

  const handleRow = (row, index) => {
    let rowStyle = {}

    if (deepConfig.is_line_height && deepConfig.is_zebra) { // 设置高亮并且设置斑马纹 高亮优先级高于斑马纹
      let lineList = deepConfig.appoint_line_heights.replaceAll('，', ',').split(',')
      const formatErr = lineList.some(d => isNaN(d))
      if (!formatErr) {
        lineList = lineList.map(d => Number(d))
        if (currentTheme?.theme === 'DARK') {
          rowStyle = lineList.includes(index + 1)
            ? { background: deepConfig.line_hgith_dark_bg }
            : { background: index % 2 === 0 ? deepConfig.zebra_odd_dark_bg : deepConfig.zebra_even_dark_bg }
        } else {
          rowStyle = lineList.includes(index + 1)
            ? { background: deepConfig.line_hgith_light_bg }
            : { background: index % 2 === 0 ? deepConfig.zebra_odd_light_bg : deepConfig.zebra_even_light_bg }
        }
      }
    } else if (deepConfig.is_line_height && !deepConfig.is_zebra) { // 只设置高亮
      let lineList = deepConfig.appoint_line_heights.replaceAll('，', ',').split(',')
      const formatErr = lineList.some(d => isNaN(d))
      if (!formatErr) {
        lineList = lineList.map(d => Number(d))
        rowStyle = lineList.includes(index + 1)
          ? { background: currentTheme?.theme === 'DARK' ? deepConfig.line_hgith_dark_bg : deepConfig.line_hgith_light_bg }
          : { background: currentTheme?.chartBgColor }
      } else {
        rowStyle = { background: currentTheme?.chartBgColor }
      }
    } else if (!deepConfig.is_line_height && deepConfig.is_zebra) { // 只设置斑马纹
      rowStyle = {
        background: index % 2 === 0
          ? (currentTheme?.theme === 'DARK' ? deepConfig.zebra_odd_dark_bg : deepConfig.zebra_odd_light_bg)
          : (currentTheme?.theme === 'DARK' ? deepConfig.zebra_even_dark_bg : deepConfig.zebra_even_light_bg)
      }
    } else { //都不设置
      rowStyle = { background: currentTheme?.chartBgColor }
    }

    return { style: { ...rowStyle } }
  }

  let rowIndex = 0
  const initScroll = (rowHeight, tableLength, hasDivider = false) => {
    clearInterval(scrollTimer)
    scrollTimer = null
    rowIndex = 0
    scrollPanel.current.scrollTop = rowIndex * rowHeight
    
    if (deepConfig.scroll_method === 'line') {
      const actualLength = hasDivider ? tableLength - 1 : tableLength
      if (!scrollTimer) {
        scrollTimer = setInterval(() => {
          if(!scrollPanel.current) {
            clearInterval(scrollTimer)
            return ;
          }
          if (rowIndex >= actualLength) {
            rowIndex = 0
            scrollPanel.current.style.scrollBehavior = ''
            scrollPanel.current.scrollTop = rowIndex * rowHeight
            rowIndex ++
            scrollPanel.current.style.scrollBehavior = 'smooth'
            scrollPanel.current.scrollTop = rowIndex * rowHeight
          } else {
            rowIndex ++
            scrollPanel.current.style.scrollBehavior = 'smooth'
            scrollPanel.current.scrollTop = rowIndex * rowHeight
          }
        }, deepConfig.scroll_time * 1000)
      }
    } else {
      const actualLength = hasDivider ? tableLength - 1 : tableLength
      if (!scrollTimer) {
        scrollTimer = setInterval(() => {
          if(!scrollPanel.current) {
            clearInterval(scrollTimer)
            return ;
          }
          if (rowIndex >= actualLength) {
            rowIndex = 0
            scrollPanel.current.style.scrollBehavior = ''
            scrollPanel.current.scrollTop = rowIndex * rowHeight
            rowIndex += line_computed(commonInfo.deepConfig)
            scrollPanel.current.style.scrollBehavior = 'smooth'
            scrollPanel.current.scrollTop = rowIndex * rowHeight
          } else if (actualLength - rowIndex <= line_computed(commonInfo.deepConfig)) {
            rowIndex += actualLength - rowIndex
            scrollPanel.current.style.scrollBehavior = 'smooth'
            scrollPanel.current.scrollTop = rowIndex * rowHeight
          } else {
            rowIndex += line_computed(commonInfo.deepConfig)
            scrollPanel.current.style.scrollBehavior = 'smooth'
            scrollPanel.current.scrollTop = rowIndex * rowHeight
          }
        }, deepConfig.scroll_time * 1000)
      }
    }
  }



  return (
    <div id="scroll-table-container">
      <Table
        id="scroll-table-header"
        style={{whiteSpace: "nowrap", textOverflow: "ellipsis", fontSize: "20px"}}
        virtualized={virtualized}
        resizable={deepConfig.is_allocation}
        pagination={false}
        columns={getColumns()}
        dataSource={tableDatas}
        scroll={scroll}
        onRow={handleRow}
        getVirtualizedListRef={(ref) => (virtualizedListRef = ref)}
      />
      <div className="scroll-panel" ref={scrollPanel}>
        <Table
          id="scroll-table-body"
          style={{fontSize: "16px"}}
          virtualized={virtualized}
          resizable={deepConfig.is_allocation}
          pagination={false}
          columns={getColumns()}
          dataSource={tableDatas}
          scroll={scroll}
          onRow={handleRow}
          getVirtualizedListRef={(ref) => (virtualizedListRef = ref)}
        />
        <Table
          id="scroll-table-body-copy"
          style={{fontSize: "16px"}}
          virtualized={virtualized}
          resizable={deepConfig.is_allocation}
          pagination={false}
          columns={getColumns()}
          dataSource={tableDatas}
          scroll={scroll}
          onRow={handleRow}
          getVirtualizedListRef={(ref) => (virtualizedListRef = ref)}
        />
      </div>
    </div>
  );
})

export default VirtualizedFixedDemo
